import java.net.URI

/** All placeholder content of the fork lives here. Images are generated by tools/GenerateZoneArt.java. */
object MockData {
    private const val IMG = "/dev/launcherfork/mock"

    /** Mock images ship on the classpath; the domain only sees the resulting URI. */
    private fun res(path: String): URI =
        requireNotNull(MockData::class.java.getResource(path)) { "Missing mock image $path" }.toURI()

