                    "открытый мир, RPG и динамичный шутер.",
            ),
            iconUri = res("$IMG/servers/stalcraft_x_icon.png"),
            backgroundUri = res("$IMG/servers/stalcraft_x_bg.jpg"),
            installed = true,
            clientSizeBytes = 18_400_000_000,
            tagline = "В ЧЕРНОБЫЛЬ",
        ),
        Server(
            id = "bravo",
            caption = "Placeholder Game",
            online = true,
            players = 342,
            description = listOf(
                "Second placeholder game. The client is not installed, so the button shows Download.",
